@pytest.mark.parametrize(
    "probe, answer",
    [(probe, answer) for _, probe, answer in PAIRS],
    ids=[case_id for case_id, _, _ in PAIRS],
)
def test_pair(probe, answer):
    assert evaluate_to_text(probe) == answer


@pytest.mark.parametrize(
    "probe",
    [probe for _, probe in REFUSED],
    ids=[case_id for case_id, _ in REFUSED],
)
def test_refused(probe):
    assert "is not supported by this engine yet" in evaluate_to_text(probe)

# ---------------------------------------------------------------------------
# 12 further tests of our own, for shapes reasoned about from the measured
# rules in the brief. Every expected value below is derived by hand from
# those rules (mode/tie-break statistics, W whitespace runs, row splitting,
# window truncation), not taken from any engine output.

def _own_probe(text_literal, delimiters):
    """Content.Type plus the Csv.PotentialDelimiters rows for `delimiters`."""
    return (
        "let r = try (let x = Text.ToBinary(" + text_literal + "),"
        " c = Binary.InferContentType(x) in"
        ' {c[Content.Type], if Record.HasFields(c, "Csv.PotentialDelimiters") then'
        " Table.ToRows(Table.SelectRows(c[Csv.PotentialDelimiters],"
        " each List.Contains(" + delimiters + ", [PotentialDelimiter])))"
        ' else "nodelim"}) in'
        ' if r[HasError] then {"E", r[Error][Reason], r[Error][Message]} else r[Value]'
    )

_CSV_COMMA_2242 = (
    'V:list:[text:"text/csv",list:['
    'list:[text:",",number:0,number:3,number:2,number:4,number:2],'
    'list:[text:",",number:1,number:3,number:2,number:4,number:2]]]'
)

_OWN_CASES = [
    # Tie-breaks (rule: a field count wins only when its count exceeds the
    # best count so far, so a mode tie goes to whichever count got there first).
    ("tie_3223",
     '"a,b,c#(lf)a,b#(lf)a,b#(lf)a,b,c"', '{","}',
     # counts 3,2,2,3 -> 2 reaches 2 first => NonEmptyColumns=2, NonEmptyRows=2
     _CSV_COMMA_2242),
    ("tie_2332",
     '"a,b#(lf)a,b,c#(lf)a,b,c#(lf)a,b"', '{","}',
     # counts 2,3,3,2 -> 3 reaches 2 first => 3 and 2 rows
     'V:list:[text:"text/csv",list:['
     'list:[text:",",number:0,number:3,number:3,number:4,number:2],'
     'list:[text:",",number:1,number:3,number:3,number:4,number:2]]]'),
    ("tie_123",
     '"a#(lf)a,b#(lf)a,b,c"', '{","}',
     # counts 1,2,3 -> no count ever beats 1's early lead => 1 and 1 row
     'V:list:[text:"text/csv",list:['
     'list:[text:",",number:0,number:3,number:1,number:3,number:1],'
     'list:[text:",",number:1,number:3,number:1,number:3,number:1]]]'),
    ("tie_323",
     '"a,b,c#(lf)a,b#(lf)a,b,c"', '{","}',
     # counts 3,2,3 -> 3's second row beats best=1 => 3 and 2 rows
     'V:list:[text:"text/csv",list:['
     'list:[text:",",number:0,number:3,number:3,number:3,number:2],'
     'list:[text:",",number:1,number:3,number:3,number:3,number:2]]]'),
    ("tie_2233",
     '"a,b#(lf)a,b#(lf)a,b,c#(lf)a,b,c"', '{","}',
     # counts 2,2,3,3 -> 2 reaches 2 first => 2 and 2 rows
     _CSV_COMMA_2242),
    # W with mixed spaces (rule: runs of space/tab/VT collapse; a leading or
    # trailing run still adds an empty field: fields = runs + 1).
    ("w_leading_spaces",
     '"  a"', '{"W"}',
     # one leading run + "a" => 2 fields, 1 row
     'V:list:[text:"text/csv",list:['
     'list:[text:"W",number:0,number:2,number:2,number:1,number:1],'
     'list:[text:"W",number:1,number:2,number:2,number:1,number:1]]]'),
    ("w_only_spaces",
     '"   "', '{"W"}',
     # one run of three spaces, nothing else => 2 fields, 1 row
     'V:list:[text:"text/csv",list:['
     'list:[text:"W",number:0,number:2,number:2,number:1,number:1],'
     'list:[text:"W",number:1,number:2,number:2,number:1,number:1]]]'),
    ("w_mixed_space_tab",
     '"a b#(tab)c"', '{"W"}',
     # runs: space, tab (separated by b) => 2 runs => 3 fields, 1 row
     'V:list:[text:"text/csv",list:['
     'list:[text:"W",number:0,number:3,number:3,number:1,number:1],'
     'list:[text:"W",number:1,number:3,number:3,number:1,number:1]]]'),
    # CR-only breaks (rule: LF, CR or CRLF each break a line).
    ("cr_only_breaks",
     '"a,b#(cr)c,d"', '{","}',
     # 2 rows, both with 2 comma fields
     'V:list:[text:"text/csv",list:['
     'list:[text:",",number:0,number:2,number:2,number:2,number:2],'
     'list:[text:",",number:1,number:2,number:2,number:2,number:2]]]'),
    ("crlf_single_break",
     '"a#(cr)#(lf)b"', '{","}',
     # CRLF is one break => 2 rows of 1 field
     'V:list:[text:"text/csv",list:['
     'list:[text:",",number:0,number:1,number:1,number:2,number:2],'
     'list:[text:",",number:1,number:1,number:1,number:2,number:2]]]'),
    # Truncation at the window edge (rule: >= 65536 bytes counts as truncated
    # and drops the last parsed row of the window; 65535 bytes does not).
    ("edge_65536_truncated",
     'Text.Repeat("a#(lf)",32768)', '{","}',
     # 65536 bytes => truncated => 32768 rows lose the last => 32767 rows of 1 field
     'V:list:[text:"text/csv",list:['
     'list:[text:",",number:0,number:1,number:1,number:32767,number:32767],'
     'list:[text:",",number:1,number:1,number:1,number:32767,number:32767]]]'),
    ("edge_65535_not_truncated",
     'Text.Repeat("a#(lf)",32767) & "a"', '{","}',
     # 65535 bytes => not truncated => the unterminated last line stays: 32768 rows
     'V:list:[text:"text/csv",list:['
     'list:[text:",",number:0,number:1,number:1,number:32768,number:32768],'
     'list:[text:",",number:1,number:1,number:1,number:32768,number:32768]]]'),
]


@pytest.mark.parametrize(
    "text_literal, delimiters, expected",
    [(text_literal, delimiters, expected) for _, text_literal, delimiters, expected in _OWN_CASES],
    ids=[case_id for case_id, _, _, _ in _OWN_CASES],
)
def test_own_shape(text_literal, delimiters, expected):
    assert evaluate_to_text(_own_probe(text_literal, delimiters)) == expected
